package com.nexushr.controller;
import com.nexushr.model.*;import com.nexushr.repo.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payroll") public class PayrollController{final PayrollRepository r;final EmployeeRepository er;public PayrollController(PayrollRepository r,EmployeeRepository e){this.r=r;er=e;} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @GetMapping public List<Payroll> all(){return r.findAll();} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PostMapping("/generate/{employeeId}") public Payroll gen(@PathVariable Long employeeId){var e=er.findById(employeeId).orElseThrow();double basic=e.salary;String period=java.time.YearMonth.now().toString();Payroll p=r.findAll().stream().filter(x->x.employee.id.equals(employeeId)&&x.period.equals(period)).findFirst().orElseGet(Payroll::new);p.employee=e;p.period=period;p.basicSalary=basic;p.hra=basic*.4;p.allowances=basic*.1667;p.grossSalary=p.basicSalary+p.hra+p.allowances;p.pf=basic*.12;p.tax=p.grossSalary*.025;p.otherDeductions=500;p.netSalary=p.grossSalary-p.pf-p.tax-p.otherDeductions;return r.save(p);} }
